/* Responsive Breakpoint for Mobile Viewports */
@media (max-width: 768px) {
  .container {
    display: flex;
    flex-direction: column;
    padding: 1rem;
  }
  .nav-menu {
    display: none; /* Collapse desktop navigation bar on compact screens */
  }
}

// Registering an event listener to mutate DOM text and styling dynamically
const button = document.querySelector('#counter-btn');
const display = document.querySelector('#count-display');
let count = 0;

button.addEventListener('click', () => {
  count++;
  display.textContent = 'Click Count: ' + count;
  display.style.color = count % 2 === 0 ? '#138a55' : '#2f5bff';
});

